                cookies_data = {}
            else:
                try:
                    cookies_data = dict(raw)
                except Exception:
                    cookies_data = {}

        self.cookies = cookies_data
        self._save_cookies()
        return self.cookies

    def load_cookies(self):
        """
        Loads the cookies from the cookies_file to the cookies data.
        :return: The cookies data, dict.
