        >>> cookies_util.load_cookies()
        {'key1': 'value1', 'key2': 'value2'}

        """
        try:
            with open(self.cookies_file, "r", encoding="utf-8") as f:
                data = json.load(f)
                if isinstance(data, dict):
                    self.cookies = data
                else:
                    self.cookies = {}
        except (FileNotFoundError, json.JSONDecodeError, OSError, TypeError, ValueError):
            self.cookies = {}
