    def caesar_decipher(self, ciphertext, shift):
        """
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,str.
        :param shift: The shift to use for decryption,int.
        :return: The deciphered plaintext,str.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        """
        if ciphertext is None:
            return ""
        if not isinstance(ciphertext, str):
            ciphertext = str(ciphertext)
        if not isinstance(shift, int):
            raise TypeError("shift must be an integer")

        result = []
        shift = shift % 26

        for ch in ciphertext:
            if 'a' <= ch <= 'z':
                result.append(chr((ord(ch) - ord('a') - shift) % 26 + ord('a')))
            elif 'A' <= ch <= 'Z':
                result.append(chr((ord(ch) - ord('A') - shift) % 26 + ord('A')))
            else:
                result.append(ch)
        return ''.join(result)

    def vigenere_decipher(self, ciphertext):
        """
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,str.
        :return: The deciphered plaintext,str.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        """
        if ciphertext is None:
            return ""
        if not isinstance(ciphertext, str):
            ciphertext = str(ciphertext)

        key = self.key if isinstance(self.key, str) else str(self.key)
        key_letters = [k.lower() for k in key if k.isalpha()]
        if not key_letters:
            return ciphertext

        result = []
        key_index = 0
        key_len = len(key_letters)

        for ch in ciphertext:
            if ch.isalpha():
                shift = ord(key_letters[key_index % key_len]) - ord('a')
                if ch.islower():
                    dec = chr((ord(ch) - ord('a') - shift) % 26 + ord('a'))
                else:
                    dec = chr((ord(ch) - ord('A') - shift) % 26 + ord('A'))
                result.append(dec)
                key_index += 1
            else:
                result.append(ch)
        return ''.join(result)

    def rail_fence_decipher(self, encrypted_text, rails):
        """
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,str.
        :param rails: The number of rails to use for decryption,int.
        :return: The deciphered plaintext,str.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        """
        if encrypted_text is None:
            return ""
        if not isinstance(encrypted_text, str):
            encrypted_text = str(encrypted_text)
        if not isinstance(rails, int):
            raise TypeError("rails must be an integer")
        if rails <= 0:
            raise ValueError("rails must be greater than 0")
        if rails == 1 or len(encrypted_text) <= 1:
            return encrypted_text

        n = len(encrypted_text)

        pattern = []
        rail = 0
        direction = 1
        for _ in range(n):
            pattern.append(rail)
            if rail == 0:
                direction = 1
            elif rail == rails - 1:
                direction = -1
            rail += direction

        rail_counts = [0] * rails
        for r in pattern:
            rail_counts[r] += 1

        rails_data = []
        idx = 0
        for count in rail_counts:
            rails_data.append(list(encrypted_text[idx:idx + count]))
            idx += count

        rail_positions = [0] * rails
        result = []
        for r in pattern:
            result.append(rails_data[r][rail_positions[r]])
            rail_positions[r] += 1

        return ''.join(result)

class DiscountStrategy:
    """
    This is a class that allows to use different discount strategy based on shopping credit or shopping cart in supermarket.
    """

    def __init__(self, customer, cart, promotion=None):
        """
        Initialize the DiscountStrategy with customer information, a cart of items, and an optional promotion.
        :param customer: dict, customer information
        :param cart: list of dicts, a cart of items with details
        :param promotion: function, optional promotion applied to the order
        >>> customer = {'name': 'John Doe', 'fidelity': 1200}
        >>> cart = [{'product': 'product', 'quantity': 14, 'price': 23.5}]
        >>> DiscountStrategy(customer, cart, DiscountStrategy.FidelityPromo)

        """
        self.customer = customer if isinstance(customer, dict) else {}
        self.cart = cart if isinstance(cart, list) else []
        self.promotion = promotion
        self._total = None
        self.total()

    def total(self):
        """
        Calculate the total cost of items in the cart.
        :return: float, total cost of items
        >>> customer = {'name': 'John Doe', 'fidelity': 1200}
        >>> cart = [{'product': 'product', 'quantity': 14, 'price': 23.5}]
        >>> ds = DiscountStrategy(customer, cart)
        >>> ds.total()
        329.0

        """
        if self._total is None:
            total_cost = 0.0
            for item in self.cart:
                if not isinstance(item, dict):
                    continue
                quantity = item.get("quantity", 0)
                price = item.get("price", 0.0)
                try:
                    quantity = float(quantity)
                    price = float(price)
                except (TypeError, ValueError):
                    continue
                if quantity < 0 or price < 0:
                    continue
                total_cost += quantity * price
            self._total = float(total_cost)
        return self._total

    def due(self):
        """
        Calculate the final amount to be paid after applying the discount.
        :return: float, final amount to be paid
        >>> customer = {'name': 'John Doe', 'fidelity': 1200}
        >>> cart = [{'product': 'product', 'quantity': 14, 'price': 23.5}]
        >>> ds = DiscountStrategy(customer, cart, DiscountStrategy.FidelityPromo)
        >>> ds.due()
        312.55

        """
        total_amount = self.total()
        if self.promotion is None:
            discount = 0.0
        else:
            try:
                discount = float(self.promotion(self))
            except Exception:
                discount = 0.0
        if discount < 0:
            discount = 0.0
        if discount > total_amount:
            discount = total_amount
        return total_amount - discount

    @staticmethod
    def FidelityPromo(order):
        """
        Calculate the discount based on the fidelity points of the customer.Customers with over 1000 points can enjoy a 5% discount on the entire order.
        :param order: object, the order to apply the discount to
        :return: float, discount amount
        >>> customer = {'name': 'John Doe', 'fidelity': 1200}
        >>> cart = [{'product': 'product', 'quantity': 14, 'price': 23.5}]
        >>> order = DiscountStrategy(customer, cart, DiscountStrategy.FidelityPromo)
        >>> DiscountStrategy.FidelityPromo(order)
        16.45

        """
        if order is None or not hasattr(order, "customer"):
            return 0.0
        fidelity = order.customer.get("fidelity", 0) if isinstance(order.customer, dict) else 0
        try:
            fidelity = float(fidelity)
        except (TypeError, ValueError):
            fidelity = 0
        if fidelity >= 1000:
            return order.total() * 0.05
        return 0.0

    @staticmethod
    def BulkItemPromo(order):
        """
        Calculate the discount based on bulk item quantity in the order.In the same order, if the quantity of a single item reaches 20 or more, each item will enjoy a 10% discount.
        :param order: object, the order to apply the discount to
        :return: float, discount amount
        >>> customer = {'name': 'John Doe', 'fidelity': 1200}
        >>> cart = [{'product': 'product', 'quantity': 20, 'price': 23.5}]
        >>> order = DiscountStrategy(customer, cart, DiscountStrategy.BulkItemPromo)
        >>> DiscountStrategy.BulkItemPromo(order)
        47.0

        """
        if order is None or not hasattr(order, "cart") or not isinstance(order.cart, list):
            return 0.0
        discount = 0.0
        for item in order.cart:
            if not isinstance(item, dict):
                continue
            quantity = item.get("quantity", 0)
            price = item.get("price", 0.0)
            try:
                quantity = float(quantity)
                price = float(price)
            except (TypeError, ValueError):
                continue
            if quantity >= 20 and price >= 0:
                discount += quantity * price * 0.10
        return float(discount)

    @staticmethod
    def LargeOrderPromo(order):
        """
        Calculate the discount based on the number of different products in the order.If the quantity of different products in the order reaches 10 or more, the entire order will enjoy a 7% discount.
        :param order: object, the order to apply the discount to
        :return: float, discount amount
        >>> customer = {'name': 'John Doe', 'fidelity': 1200}
        >>> cart = [{'product': 'product', 'quantity': 14, 'price': 23.5}]
        >>> order = DiscountStrategy(customer, cart, DiscountStrategy.LargeOrderPromo)
        >>> DiscountStrategy.LargeOrderPromo(order)
        0.0

        """
        if order is None or not hasattr(order, "cart") or not isinstance(order.cart, list):
            return 0.0
        distinct_products = set()
        for item in order.cart:
            if isinstance(item, dict) and "product" in item:
                distinct_products.add(item["product"])
        if len(distinct_products) >= 10:
            return order.total() * 0.07
        return 0.0

