from decimal import Decimal, DivisionByZero, InvalidOperation


class ExpressionCalculator:
    """
    This is a class in Python that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    """

    def __init__(self):
        """
        Initialize the expression calculator
        """
        self.postfix_stack = deque()
        self.operat_priority = [0, 3, 2, 1, -1, 1, 0, 2]

    def calculate(self, expression):
        """
        Calculate the result of the given postfix expression
        :param expression: string, the postfix expression to be calculated
        :return: float, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.calculate("2 + 3 * 4")
        14.0

        """
        if expression is None:
            raise ValueError("expression cannot be None")
        expression = self.transform(expression)
        if expression == "":
            raise ValueError("expression cannot be empty")

        self.prepare(expression)
        if not self.postfix_stack:
            raise ValueError("invalid expression")

        stack = deque()
        for token in self.postfix_stack:
            if not self.is_operator(token):
                stack.append(token)
            else:
                if len(stack) < 2:
                    raise ValueError("invalid expression")
                second_value = stack.pop()
                first_value = stack.pop()
                result = self._calculate(first_value, second_value, token)
                stack.append(str(result))

        if len(stack) != 1:
            raise ValueError("invalid expression")

        return float(Decimal(stack.pop()))

    def prepare(self, expression):
        """
        Prepare the infix expression for conversion to postfix notation
        :param expression: string, the infix expression to be prepared
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.prepare("2+3*4")

        expression_calculator.postfix_stack = ['2', '3', '4', '*', '+']
        """
        if expression is None:
            raise ValueError("expression cannot be None")
        expression = self.transform(expression)
        if expression == "":
            self.postfix_stack = deque()
            return

        self.postfix_stack = deque()
        operator_stack = deque()
        number_buffer = []

        def flush_number():
            if number_buffer:
                self.postfix_stack.append("".join(number_buffer))
                number_buffer.clear()

        for ch in expression:
            if ch.isdigit() or ch == ".":
                number_buffer.append(ch)
            elif self.is_operator(ch):
                flush_number()
                if ch == "(":
                    operator_stack.append(ch)
                elif ch == ")":
                    while operator_stack and operator_stack[-1] != "(":
                        self.postfix_stack.append(operator_stack.pop())
                    if not operator_stack:
                        raise ValueError("mismatched parentheses")
                    operator_stack.pop()
                else:
                    while (
                        operator_stack
                        and operator_stack[-1] != "("
                        and self.compare(ch, operator_stack[-1])
                    ):
                        self.postfix_stack.append(operator_stack.pop())
                    operator_stack.append(ch)
            else:
                raise ValueError(f"invalid character: {ch}")

        flush_number()

        while operator_stack:
            op = operator_stack.pop()
            if op in ("(", ")"):
                raise ValueError("mismatched parentheses")
            self.postfix_stack.append(op)

    @staticmethod
    def is_operator(c):
        """
        Check if a character is an operator in {'+', '-', '*', '/', '(', ')', '%'}
        :param c: string, the character to be checked
        :return: bool, True if the character is an operator, False otherwise
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.is_operator("+")
        True

        """
        return c in {"+", "-", "*", "/", "(", ")", "%"}

    def compare(self, cur, peek):
        """
        Compare the precedence of two operators
        :param cur: string, the current operator
        :param peek: string, the operator at the top of the operator stack
        :return: bool, True if the current operator has higher or equal precedence, False otherwise
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.compare("+", "-")
        True

        """
        priority = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2}
        if cur not in priority or peek not in priority:
            return False
        return priority[cur] <= priority[peek]

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        """
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: string, the first operand
        :param second_value: string, the second operand
        :param current_op: string, the operator
        :return: decimal.Decimal, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator._calculate("2", "3", "+")
        5.0

        """
        try:
            a = Decimal(str(first_value))
            b = Decimal(str(second_value))
        except (InvalidOperation, ValueError):
            raise ValueError("invalid numeric value")

        try:
            if current_op == "+":
                return a + b
            if current_op == "-":
                return a - b
            if current_op == "*":
                return a * b
            if current_op == "/":
                return a / b
            if current_op == "%":
                return a % b
        except DivisionByZero:
            raise ZeroDivisionError("division/modulo by zero")

        raise ValueError(f"unsupported operator: {current_op}")

    @staticmethod
    def transform(expression):
        """
        Transform the infix expression to a format suitable for conversion
        :param expression: string, the infix expression to be transformed
        :return: string, the transformed expression
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.transform("2 + 3 * 4")
        "2+3*4"

        """
        if expression is None:
            return ""
        return "".join(str(expression).split())

class FitnessTracker:
    """
    This is a class as fitness tracker that implements to calculate BMI (Body Mass Index) and calorie intake based on the user's height, weight, age, and sex.
    """

    def __init__(self, height, weight, age, sex) -> None:
        """
        Initialize the class with height, weight, age, and sex, and calculate the BMI standard based on sex, and male is 20-25, female is 19-24.
        """
        self.height = height
        self.weight = weight
        self.age = age
        self.sex = sex
        self.BMI_std = [
            {"male": [20, 25]},
            {"female": [19, 24]}
        ]

    def get_BMI(self):
        """
        Calculate the BMI based on the height and weight.
        :return: BMI,which is the weight divide by the square of height, float.
        >>> fitnessTracker = FitnessTracker(1.8, 70, 20, "male")
        >>> fitnessTracker.get_BMI()
        21.604938271604937

        """
        if self.height is None or self.weight is None:
            raise ValueError("height and weight must not be None")
        try:
            height = float(self.height)
            weight = float(self.weight)
        except (TypeError, ValueError):
            raise ValueError("height and weight must be numeric")
        if height <= 0:
            raise ValueError("height must be greater than 0")
        if weight < 0:
            raise ValueError("weight must be non-negative")
        return weight / (height ** 2)

    def condition_judge(self):
        """
        Judge the condition of the user based on the BMI standard.
        :return: 1 if the user is too fat, -1 if the user is too thin, 0 if the user is normal, int.
        >>> fitnessTracker = FitnessTracker(1.8, 70, 20, "male")
        >>> fitnessTracker.condition_judge()
        -1

        """
        if self.sex is None:
            raise ValueError("sex must not be None")
        sex = str(self.sex).strip().lower()
        bmi = self.get_BMI()

        if sex == "male":
            low, high = self.BMI_std[0]["male"]
        elif sex == "female":
            low, high = self.BMI_std[1]["female"]
        else:
            raise ValueError("sex must be 'male' or 'female'")

        if bmi > high:
            return 1
        elif bmi < low:
            return -1
        return 0

    def calculate_calorie_intake(self):
        """
        Calculate the calorie intake based on the user's condition and BMR (Basal Metabolic Rate),BMR is calculated based on the user's height, weight, age, and sex,male is10 * self.weight + 6.25 * self.height - 5 * self.age + 5,female is 10 * self.weight + 6.25 * self.height - 5 * self.age - 161, and the calorie intake is calculated based on the BMR and the user's condition,if the user is too fat, the calorie intake is BMR * 1.2, if the user is too thin, the calorie intake is BMR * 1.6, if the user is normal, the calorie intake is BMR * 1.4.
        :return: calorie intake, float.
        >>> fitnessTracker = FitnessTracker(1.8, 70, 20, "male")
        >>> fitnessTracker.calculate_calorie_intake()
        986.0

        """
        if self.weight is None or self.height is None or self.age is None:
            raise ValueError("height, weight, and age must not be None")
        try:
            weight = float(self.weight)
            height = float(self.height)
            age = float(self.age)
        except (TypeError, ValueError):
            raise ValueError("height, weight, and age must be numeric")
        if weight < 0 or height <= 0 or age < 0:
            raise ValueError("weight must be >= 0, height > 0, and age >= 0")

        if self.sex is None:
            raise ValueError("sex must not be None")
        sex = str(self.sex).strip().lower()

        if sex == "male":
            bmr = 10 * weight + 6.25 * height - 5 * age + 5
        elif sex == "female":
            bmr = 10 * weight + 6.25 * height - 5 * age - 161
        else:
            raise ValueError("sex must be 'male' or 'female'")

        condition = self.condition_judge()
        if condition == 1:
            return bmr * 1.2
        elif condition == -1:
            return bmr * 1.6
        return bmr * 1.4

class Interpolation:
    """
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    """

    def __init__(self):
        pass

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        """
        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :return: The y-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_1d([1, 2, 3], [1, 2, 3], [1.5, 2.5])
        [1.5, 2.5]
        """
        if x is None or y is None or x_interp is None:
            return []
        if len(x) == 0 or len(y) == 0 or len(x_interp) == 0:
            return []
        if len(x) != len(y):
            raise ValueError("x and y must have the same length.")
        if len(x) < 2:
            raise ValueError("At least two data points are required for interpolation.")

        points = sorted(zip(x, y), key=lambda p: p[0])
        xs = [p[0] for p in points]
        ys = [p[1] for p in points]

        for i in range(1, len(xs)):
            if xs[i] == xs[i - 1]:
                raise ValueError("x values must be strictly increasing (no duplicates).")

        def interp_single(xq):
            if xq <= xs[0]:
                x0, x1 = xs[0], xs[1]
                y0, y1 = ys[0], ys[1]
            elif xq >= xs[-1]:
                x0, x1 = xs[-2], xs[-1]
                y0, y1 = ys[-2], ys[-1]
            else:
                left, right = 0, len(xs) - 1
                while left <= right:
                    mid = (left + right) // 2
                    if xs[mid] == xq:
                        return ys[mid]
                    if xs[mid] < xq:
                        left = mid + 1
                    else:
                        right = mid - 1
                i1 = left
                i0 = i1 - 1
                x0, x1 = xs[i0], xs[i1]
                y0, y1 = ys[i0], ys[i1]

            return y0 + (y1 - y0) * (xq - x0) / (x1 - x0)

        return [float(interp_single(v)) for v in x_interp]

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        """
        Linear interpolation of two-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param z: The z-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :param y_interp: The y-coordinate of the interpolation point, list.
        :return: The z-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_2d([1, 2, 3], [1, 2, 3], [[1, 2, 3], [4, 5, 6], [7, 8, 9]], [1.5, 2.5], [1.5, 2.5])
        [3.0, 7.0]
        """
        if x is None or y is None or z is None or x_interp is None or y_interp is None:
            return []
        if len(x) == 0 or len(y) == 0 or len(z) == 0 or len(x_interp) == 0 or len(y_interp) == 0:
            return []
        if len(x_interp) != len(y_interp):
            raise ValueError("x_interp and y_interp must have the same length.")
        if len(x) < 2 or len(y) < 2:
            raise ValueError("x and y must each contain at least two points.")
        if len(z) != len(y):
            raise ValueError("z must have the same number of rows as len(y).")
        if any(len(row) != len(x) for row in z):
            raise ValueError("Each row in z must have length len(x).")

        x_idx_sorted = sorted(range(len(x)), key=lambda i: x[i])
        y_idx_sorted = sorted(range(len(y)), key=lambda i: y[i])

        xs = [x[i] for i in x_idx_sorted]
        ys = [y[j] for j in y_idx_sorted]
        zs = [[z[j][i] for i in x_idx_sorted] for j in y_idx_sorted]

        for i in range(1, len(xs)):
            if xs[i] == xs[i - 1]:
                raise ValueError("x values must be strictly increasing (no duplicates).")
        for j in range(1, len(ys)):
            if ys[j] == ys[j - 1]:
                raise ValueError("y values must be strictly increasing (no duplicates).")

        def bracket(arr, q):
            if q <= arr[0]:
                return 0, 1
            if q >= arr[-1]:
                return len(arr) - 2, len(arr) - 1

            left, right = 0, len(arr) - 1
            while left <= right:
                mid = (left + right) // 2
                if arr[mid] == q:
                    return mid, mid
                if arr[mid] < q:
                    left = mid + 1
                else:
                    right = mid - 1
            return left - 1, left

        out = []
        for xq, yq in zip(x_interp, y_interp):
            i0, i1 = bracket(xs, xq)
            j0, j1 = bracket(ys, yq)

            if i0 == i1 and j0 == j1:
                val = zs[j0][i0]
            elif i0 == i1:
                y0, y1 = ys[j0], ys[j1]
                z0, z1 = zs[j0][i0], zs[j1][i0]
                val = z0 + (z1 - z0) * (yq - y0) / (y1 - y0)
            elif j0 == j1:
                x0, x1 = xs[i0], xs[i1]
                z0, z1 = zs[j0][i0], zs[j0][i1]
                val = z0 + (z1 - z0) * (xq - x0) / (x1 - x0)
            else:
                x0, x1 = xs[i0], xs[i1]
                y0, y1 = ys[j0], ys[j1]
                z00 = zs[j0][i0]
                z10 = zs[j0][i1]
                z01 = zs[j1][i0]
                z11 = zs[j1][i1]

                tx = (xq - x0) / (x1 - x0)
                ty = (yq - y0) / (y1 - y0)

                val = (
                    z00 * (1 - tx) * (1 - ty) +
                    z10 * tx * (1 - ty) +
                    z01 * (1 - tx) * ty +
                    z11 * tx * ty
                )

            out.append(float(val))

        return out

import json
import os


class JSONProcessor:
    """
    This is a class to process JSON file, including reading and writing JSON files,
    as well as processing JSON data by removing a specified key from the JSON object.
    """

    def read_json(self, file_path):
        """
        Read a JSON file and return the data.
        :param file_path: str, the path of the JSON file.
        :return: dict, the data from the JSON file if read successfully, or return -1 if an error occurs during the reading process.
                    return 0 if the file does not exist.
        >>> json.read_json('test.json')
        {'name': 'test', 'age': 14}
        """
        try:
            if not file_path or not isinstance(file_path, str):
                return -1

            if not os.path.exists(file_path):
                return 0

            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)

            if isinstance(data, dict):
                return data
            return -1
        except Exception:
            return -1

    def write_json(self, data, file_path):
        """
        Write data to a JSON file and save it to the given path.

        :param data: dict, the data to be written to the JSON file.
        :param file_path: str, the path of the JSON file.
        :return: 1 if the writing process is successful, or -1, if an error occurs during the writing process.
        >>> json.write_json({'key1': 'value1', 'key2': 'value2'}, 'test.json')
        1
        >>> json.read_json('test.json')
        {'key1': 'value1', 'key2': 'value2'}
        """
        try:
            if not isinstance(data, dict):
                return -1
            if not file_path or not isinstance(file_path, str):
                return -1

            parent_dir = os.path.dirname(os.path.abspath(file_path))
            if parent_dir and not os.path.exists(parent_dir):
                os.makedirs(parent_dir, exist_ok=True)

            with open(file_path, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False)

            return 1
        except Exception:
            return -1

    def process_json(self, file_path, remove_key):
        """
        read a JSON file and process the data by removing a specified key and rewrite the modified data back to the file.

        :param file_path: str, the path of the JSON file.
        :param remove_key: str, the key to be removed.
        :return: 1, if the specified key is successfully removed and the data is written back.
                    0, if the file does not exist or the specified key does not exist in the data.
        >>> json.read_json('test.json')
        {'key1': 'value1', 'key2': 'value2'}
        >>> json.process_json('test.json', 'key1')
        1
        >>> json.read_json('test.json')
        {'key2': 'value2'}
        """
        if not file_path or not isinstance(file_path, str):
            return 0
        if not isinstance(remove_key, str) or remove_key == "":
            return 0

        data = self.read_json(file_path)

        if data == 0:
            return 0
        if data == -1 or not isinstance(data, dict):
            return 0

        if remove_key not in data:
            return 0

        try:
            del data[remove_key]
            write_result = self.write_json(data, file_path)
            return 1 if write_result == 1 else 0
        except Exception:
            return 0

import re
from collections import Counter


class NLPDataProcessor2:
    """
    The class processes NLP data by extracting words from a list of strings, calculating the frequency of each word, and returning the top 5 most frequent words.
    """

    def process_data(self, string_list):
        """
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words.
        :param string_list: a list of strings
        :return: words_list: a list of words lists
        >>> NLPDataProcessor.process_data(['This is a test.'])
        [['this', 'is', 'a', 'test']]
        """
        if string_list is None:
            return []
        if not isinstance(string_list, list):
            raise TypeError("string_list must be a list of strings or None")

        words_list = []
        for s in string_list:
            if s is None:
                cleaned = ""
            else:
                if not isinstance(s, str):
                    s = str(s)
                cleaned = re.sub(r"[^A-Za-z\s]", "", s).lower()
            words = cleaned.split()
            words_list.append(words)
        return words_list

    def calculate_word_frequency(self, words_list):
        """
        Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param words_list: a list of words lists
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.calculate_word_frequency([['this', 'is', 'a', 'test'], ['this', 'is', 'another', 'test']])
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        """
        if words_list is None:
            return {}
        if not isinstance(words_list, list):
            raise TypeError("words_list must be a list of word lists or None")

        counter = Counter()
        for words in words_list:
            if words is None:
                continue
            if not isinstance(words, list):
                raise TypeError("Each item in words_list must be a list of words")
            for w in words:
                if w is None:
                    continue
                if not isinstance(w, str):
                    w = str(w)
                if w:
                    counter[w] += 1

        sorted_items = sorted(counter.items(), key=lambda x: (-x[1],))
        top_5 = dict(sorted_items[:5])
        return top_5

    def process(self, string_list):
        """
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words. Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param string_list: a list of strings
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.process(['This is a test.', 'This is another test.'])
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        """
        words_list = self.process_data(string_list)
        return self.calculate_word_frequency(words_list)

class NumberConverter:
    """
    The class allows to convert  decimal to binary, octal and hexadecimal repectively and contrarily
    """

    @staticmethod
    def decimal_to_binary(decimal_num):
        """
        Convert a number from decimal format to binary format.
        :param decimal_num: int, decimal number
        :return: str, the binary representation of an integer.
        >>> NumberConverter.decimal_to_binary(42423)
        '1010010110110111'
        """
        if decimal_num is None:
            raise ValueError("decimal_num cannot be None")
        if not isinstance(decimal_num, int):
            raise TypeError("decimal_num must be an int")
        if decimal_num < 0:
            raise ValueError("decimal_num must be non-negative")
        return format(decimal_num, "b")

    @staticmethod
    def binary_to_decimal(binary_num):
        """
        Convert a number from binary format to decimal format.
        :param binary_num: str, binary number
        :return: int, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        """
        if binary_num is None:
            raise ValueError("binary_num cannot be None")
        if not isinstance(binary_num, str):
            raise TypeError("binary_num must be a str")
        binary_num = binary_num.strip()
        if binary_num == "":
            raise ValueError("binary_num cannot be empty")
        if binary_num.startswith("-"):
            raise ValueError("binary_num must be non-negative")
        if any(ch not in "01" for ch in binary_num):
            raise ValueError("binary_num must contain only '0' and '1'")
        return int(binary_num, 2)

    @staticmethod
    def decimal_to_octal(decimal_num):
        """
        Convert a number from decimal format to octal format.
        :param decimal_num: int, decimal number
        :return: str, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        """
        if decimal_num is None:
            raise ValueError("decimal_num cannot be None")
        if not isinstance(decimal_num, int):
            raise TypeError("decimal_num must be an int")
        if decimal_num < 0:
            raise ValueError("decimal_num must be non-negative")
        return format(decimal_num, "o")

    @staticmethod
    def octal_to_decimal(octal_num):
        """
        Convert a number from octal format to decimal format.
        :param octal_num: str, octal num
        :return: int, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        """
        if octal_num is None:
            raise ValueError("octal_num cannot be None")
        if not isinstance(octal_num, str):
            raise TypeError("octal_num must be a str")
        octal_num = octal_num.strip()
        if octal_num == "":
            raise ValueError("octal_num cannot be empty")
        if octal_num.startswith("-"):
            raise ValueError("octal_num must be non-negative")
        if any(ch not in "01234567" for ch in octal_num):
            raise ValueError("octal_num must contain only digits 0-7")
        return int(octal_num, 8)

    @staticmethod
    def decimal_to_hex(decimal_num):
        """
        Convert a number from decimal format to hex format.
        :param decimal_num: int, decimal number
        :return hex_num: str, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        """
        if decimal_num is None:
            raise ValueError("decimal_num cannot be None")
        if not isinstance(decimal_num, int):
            raise TypeError("decimal_num must be an int")
        if decimal_num < 0:
            raise ValueError("decimal_num must be non-negative")
        return format(decimal_num, "x")

    @staticmethod
    def hex_to_decimal(hex_num):
        """
        Convert a number from hex format to decimal format.
        :param hex_num: str, hex num
        :return: int, the decimal representation of hex number str.
        >>> NumberConverter.hex_to_decimal('a5b7')
        42423
        """
        if hex_num is None:
            raise ValueError("hex_num cannot be None")
        if not isinstance(hex_num, str):
            raise TypeError("hex_num must be a str")
        hex_num = hex_num.strip()
        if hex_num == "":
            raise ValueError("hex_num cannot be empty")
        if hex_num.startswith("-"):
            raise ValueError("hex_num must be non-negative")
        valid = set("0123456789abcdefABCDEF")
        if any(ch not in valid for ch in hex_num):
            raise ValueError("hex_num must contain only hexadecimal digits")
        return int(hex_num, 16)

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        """
        if string is None:
            return None

        if not isinstance(string, str):
            string = str(string)

        if string == "":
            return ""

        result = []
        i = 0
        n = len(string)

        while i < n:
            if string[i] == "&" and i + 2 < n and string[i + 1] == "#":
                j = i + 2
                is_hex = False

                if j < n and string[j] in ("x", "X"):
                    is_hex = True
                    j += 1

                start_digits = j

                while j < n:
                    ch = string[j]
                    if is_hex:
                        if self.is_hex_char(ch):
                            j += 1
                        else:
                            break
                    else:
                        if ch.isdigit():
                            j += 1
                        else:
                            break

                if j > start_digits and j < n and string[j] == ";":
                    num_str = string[start_digits:j]
                    try:
                        codepoint = int(num_str, 16 if is_hex else 10)
                        if 0 <= codepoint <= 0x10FFFF:
                            result.append(chr(codepoint))
                            i = j + 1
                            continue
                    except (ValueError, OverflowError):
                        pass

            result.append(string[i])
            i += 1

        return "".join(result)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True

        """
        return isinstance(char, str) and len(char) == 1 and (
            "0" <= char <= "9" or "a" <= char.lower() <= "f"
        )

class ShoppingCart:
    """
    The class manages items, their prices, quantities, and allows to for add, removie, view items, and calculate the total price.
    """

    def __init__(self):
        """
        Initialize the items representing the shopping list as an empty dictionary
        """
        self.items = {}

    def add_item(self, item, price, quantity=1):
        """
        Add item information to the shopping list items, including price and quantity. The default quantity is 1
        :param item: string, Item to be added
        :param price: float, The price of the item
        :param quantity:int, The number of items, defaults to 1
        :return:None
        >>> shoppingcart = ShoppingCart()
        >>> shoppingcart.add_item("apple", 1, 5)
        self.items = {"apple":{"price":1, "quantity":5}}
        """
        if item is None or not isinstance(item, str) or item.strip() == "":
            raise ValueError("item must be a non-empty string")
        if price is None:
            raise ValueError("price cannot be None")
        if quantity is None:
            raise ValueError("quantity cannot be None")
        if not isinstance(quantity, int):
            raise TypeError("quantity must be an integer")
        if quantity <= 0:
            raise ValueError("quantity must be greater than 0")
        try:
            price = float(price)
        except (TypeError, ValueError):
            raise TypeError("price must be a number")
        if price < 0:
            raise ValueError("price cannot be negative")

        key = item.strip()
        if key in self.items:
            self.items[key]["quantity"] += quantity
            self.items[key]["price"] = price
        else:
            self.items[key] = {"price": price, "quantity": quantity}

    def remove_item(self, item, quantity=1):
        """
        Subtract the specified quantity of item from the shopping list items
        :param item:string, Item to be subtracted in quantity
        :param quantity:int, Quantity to be subtracted
        :return:None
        >>> shoppingcart.add_item("apple", 1, 5)
        >>> shoppingcart.remove_item("apple", 3)
        self.items = {"apple":{"price":1, "quantity":2}}
        """
        if item is None or not isinstance(item, str) or item.strip() == "":
            raise ValueError("item must be a non-empty string")
        if quantity is None:
            raise ValueError("quantity cannot be None")
        if not isinstance(quantity, int):
            raise TypeError("quantity must be an integer")
        if quantity <= 0:
            raise ValueError("quantity must be greater than 0")

        key = item.strip()
        if key not in self.items:
            raise KeyError(f"item '{key}' not found in cart")

        self.items[key]["quantity"] -= quantity
        if self.items[key]["quantity"] <= 0:
            del self.items[key]

    def view_items(self) -> dict:
        """
        Return the current shopping list items
        :return:dict, the current shopping list items
        >>> shoppingcart.add_item("apple", 1, 5)
        >>> shoppingcart.remove_item("apple", 3)
        >>> shoppingcart.view_items()
        {"apple":{"price":1, "quantity":2}}
        """
        return {k: {"price": v["price"], "quantity": v["quantity"]} for k, v in self.items.items()}

    def total_price(self) -> float:
        """
        Calculate the total price of all items in the shopping list, which is the quantity of each item multiplied by the price
        :return:float, the total price of all items in the shopping list
        >>> shoppingcart = ShoppingCart()
        >>> shoppingcart.add_item("apple", 1, 5)
        >>> shoppingcart.add_item("banana", 2, 3)
        >>> shoppingcart.total_price()
        11.0
        """
        return float(sum(v["price"] * v["quantity"] for v in self.items.values()))

class SQLQueryBuilder:
    """
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements.
    """

    @staticmethod
    def _validate_table(table):
        if not isinstance(table, str) or not table.strip():
            raise ValueError("table must be a non-empty string")
        return table.strip()

    @staticmethod
    def _format_value(value):
        if value is None:
            return "NULL"
        return f"'{str(value)}'"

    @staticmethod
    def _build_where(where):
        if where is None:
            return ""
        if not isinstance(where, dict):
            raise ValueError("where must be a dict or None")
        if not where:
            return ""
        parts = [f"{key}={SQLQueryBuilder._format_value(val)}" for key, val in where.items()]
        return " WHERE " + " AND ".join(parts)

    @staticmethod
    def select(table, columns='*', where=None):
        """
        Generate the SELECT SQL statement from the given parameters.
        :param table: str, the query table in database.
        :param columns: list of str, ['col1', 'col2'].
        :param where: dict, {key1: value1, key2: value2 ...}. The query condition.
        return query: str, the SQL query statement.
        >>> SQLQueryBuilder.select('table1', columns = ["col1","col2"], where = {"age": 15})
        "SELECT col1, col2 FROM table1 WHERE age='15'"
        """
        table = SQLQueryBuilder._validate_table(table)

        if columns == '*':
            columns_sql = "*"
        elif isinstance(columns, (list, tuple)):
            if not columns:
                columns_sql = "*"
            else:
                columns_sql = ", ".join(str(col) for col in columns)
        elif isinstance(columns, str) and columns.strip():
            columns_sql = columns.strip()
        else:
            raise ValueError("columns must be '*', a non-empty string, or a list/tuple of column names")

        return f"SELECT {columns_sql} FROM {table}{SQLQueryBuilder._build_where(where)}"

    @staticmethod
    def insert(table, data):
        """
        Generate the INSERT SQL statement from the given parameters.
        :param table: str, the table to be inserted in database.
        :param data: dict, the key and value in SQL insert statement
        :return query: str, the SQL insert statement.
        >>> SQLQueryBuilder.insert('table1', {'name': 'Test', 'age': 14})
        "INSERT INTO table1 (name, age) VALUES ('Test', '14')"
        """
        table = SQLQueryBuilder._validate_table(table)
        if not isinstance(data, dict) or not data:
            raise ValueError("data must be a non-empty dict")

        keys = ", ".join(str(k) for k in data.keys())
        values = ", ".join(SQLQueryBuilder._format_value(v) for v in data.values())
        return f"INSERT INTO {table} ({keys}) VALUES ({values})"

    @staticmethod
    def delete(table, where=None):
        """
        Generate the DELETE SQL statement from the given parameters.
        :param table: str, the table that will be excuted with DELETE operation in database
        :param where: dict, {key1: value1, key2: value2 ...}. The query condition.
        :return query: str, the SQL delete statement.
        >>> SQLQueryBuilder.delete('table1', {'name': 'Test', 'age': 14})
        "DELETE FROM table1 WHERE name='Test' AND age='14'"
        """
        table = SQLQueryBuilder._validate_table(table)
        return f"DELETE FROM {table}{SQLQueryBuilder._build_where(where)}"

    @staticmethod
    def update(table, data, where=None):
        """
        Generate the UPDATE SQL statement from the given parameters.
        :param table: str, the table that will be excuted with UPDATE operation in database
        :param data: dict, the key and value in SQL update statement
        :param where: dict, {key1: value1, key2: value2 ...}. The query condition.
        >>> SQLQueryBuilder.update('table1', {'name': 'Test2', 'age': 15}, where = {'name':'Test'})
        "UPDATE table1 SET name='Test2', age='15' WHERE name='Test'"
        """
        table = SQLQueryBuilder._validate_table(table)
        if not isinstance(data, dict) or not data:
            raise ValueError("data must be a non-empty dict")

        set_clause = ", ".join(f"{k}={SQLQueryBuilder._format_value(v)}" for k, v in data.items())
        return f"UPDATE {table} SET {set_clause}{SQLQueryBuilder._build_where(where)}"

class URLHandler:
    """
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    """

    def __init__(self, url):
        """
        Initialize URLHandler's URL
        """
        self.url = "" if url is None else str(url)

    def get_scheme(self):
        """
        get the scheme of the URL
        :return: string, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        """
        if not self.url:
            return ""
        idx = self.url.find("://")
        if idx != -1:
            return self.url[:idx]
        idx = self.url.find(":")
        if idx != -1:
            return self.url[:idx]
        return ""

    def get_host(self):
        """
        Get the second part of the URL, which is the host domain name
        :return: string, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        """
        if not self.url:
            return ""

        start = 0
        scheme_sep = self.url.find("://")
        if scheme_sep != -1:
            start = scheme_sep + 3
        elif self.url.startswith("//"):
            start = 2

        end = len(self.url)
        for sep in ("/", "?", "#"):
            i = self.url.find(sep, start)
            if i != -1:
                end = min(end, i)

        host = self.url[start:end]
        if "@" in host:
            host = host.split("@", 1)[1]
        if ":" in host:
            host = host.split(":", 1)[0]
        return host

    def get_path(self):
        """
        Get the third part of the URL, which is the address of the resource
        :return: string, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        """
        if not self.url:
            return ""

        start = 0
        scheme_sep = self.url.find("://")
        if scheme_sep != -1:
            start = scheme_sep + 3
        elif self.url.startswith("//"):
            start = 2

        first_path_sep = self.url.find("/", start)
        if first_path_sep == -1:
            q_idx = self.url.find("?", start)
            f_idx = self.url.find("#", start)
            if q_idx != -1:
                return self.url[q_idx:]
            if f_idx != -1:
                return self.url[f_idx:]
            return ""
        return self.url[first_path_sep:]

    def get_query_params(self):
        """
        Get the request parameters for the URL
        :return: dict, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        """
        params = {}
        if not self.url:
            return params

        q_idx = self.url.find("?")
        if q_idx == -1:
            return params

        frag_idx = self.url.find("#", q_idx + 1)
        query = self.url[q_idx + 1:] if frag_idx == -1 else self.url[q_idx + 1:frag_idx]
        if not query:
            return params

        for pair in query.split("&"):
            if not pair:
                continue
            if "=" in pair:
                k, v = pair.split("=", 1)
            else:
                k, v = pair, ""
            if k:
                params[k] = v
        return params

    def get_fragment(self):
        """
        Get the fragment after '#' in the URL
        :return: string, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        """
        if not self.url:
            return ""
        idx = self.url.find("#")
        if idx == -1:
            return ""
        return self.url[idx + 1:]

import numpy as np
from gensim import matutils
from numpy import dot, array


class VectorUtil:
    """
    The class provides vector operations, including calculating similarity, cosine similarities, average similarity, and IDF weights.
    """

    @staticmethod
    def similarity(vector_1, vector_2):
        """
        Compute the cosine similarity between one vector and another vector.
        :param vector_1: numpy.ndarray, Vector from which similarities are to be computed, expected shape (dim,).
        :param vector_2: numpy.ndarray, Vector from which similarities are to be computed, expected shape (dim,).
        :return: numpy.ndarray, Contains cosine distance between `vector_1` and `vector_2`
        >>> vector_1 = np.array([1, 1])
        >>> vector_2 = np.array([1, 0])
        >>> VectorUtil.similarity(vector_1, vector_2)
        0.7071067811865475
        """
        if vector_1 is None or vector_2 is None:
            return 0.0

        v1 = np.asarray(vector_1, dtype=float)
        v2 = np.asarray(vector_2, dtype=float)

        if v1.size == 0 or v2.size == 0:
            return 0.0
        if v1.shape != v2.shape:
            raise ValueError("vector_1 and vector_2 must have the same shape.")

        return float(matutils.unitvec(v1).dot(matutils.unitvec(v2)))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        """
        Compute cosine similarities between one vector and a set of other vectors.
        :param vector_1: numpy.ndarray, Vector from which similarities are to be computed, expected shape (dim,).
        :param vectors_all: list of numpy.ndarray, For each row in vectors_all, distance from vector_1 is computed, expected shape (num_vectors, dim).
        :return: numpy.ndarray, Contains cosine distance between `vector_1` and each row in `vectors_all`, shape (num_vectors,).
        >>> vector1 = np.array([1, 2, 3])
        >>> vectors_all = [np.array([4, 5, 6]), np.array([7, 8, 9])]
        >>> VectorUtil.cosine_similarities(vector1, vectors_all)
        [0.97463185 0.95941195]
        """
        if vector_1 is None or vectors_all is None:
            return np.array([], dtype=float)

        v1 = np.asarray(vector_1, dtype=float)
        if v1.size == 0:
            return np.array([], dtype=float)

        if len(vectors_all) == 0:
            return np.array([], dtype=float)

        all_vecs = np.asarray(vectors_all, dtype=float)
        if all_vecs.ndim == 1:
            all_vecs = all_vecs.reshape(1, -1)

        if all_vecs.shape[1] != v1.shape[0]:
            raise ValueError("Each vector in vectors_all must have the same dimension as vector_1.")

        norm = np.linalg.norm(v1)
        if norm == 0.0:
            return np.zeros(all_vecs.shape[0], dtype=float)

        v1_u = v1 / norm
        all_norms = np.linalg.norm(all_vecs, axis=1)
        sims = np.zeros(all_vecs.shape[0], dtype=float)

        nonzero = all_norms != 0.0
        if np.any(nonzero):
            sims[nonzero] = dot(all_vecs[nonzero], v1_u) / all_norms[nonzero]

        return sims

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        """
        Compute cosine similarity between two sets of vectors.
        :param vector_list_1: list of numpy vector
        :param vector_list_2: list of numpy vector
        :return: numpy.ndarray, Similarities between vector_list_1 and vector_list_2.
        >>> vector_list1 = [np.array([1, 2, 3]), np.array([4, 5, 6])]
        >>> vector_list2 = [np.array([7, 8, 9]), np.array([10, 11, 12])]
        >>> VectorUtil.n_similarity(vector_list1, vector_list2)
        0.9897287473881233
        """
        if not vector_list_1 or not vector_list_2:
            return 0.0

        arr1 = np.asarray(vector_list_1, dtype=float)
        arr2 = np.asarray(vector_list_2, dtype=float)

        if arr1.ndim == 1:
            arr1 = arr1.reshape(1, -1)
        if arr2.ndim == 1:
            arr2 = arr2.reshape(1, -1)

        if arr1.shape[1] != arr2.shape[1]:
            raise ValueError("Vectors in both lists must have the same dimension.")

        mean1 = array(arr1).mean(axis=0)
        mean2 = array(arr2).mean(axis=0)

        if np.linalg.norm(mean1) == 0.0 or np.linalg.norm(mean2) == 0.0:
            return 0.0

        return float(dot(matutils.unitvec(mean1), matutils.unitvec(mean2)))

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        """
        Calculate log(total_num+1/count+1) for each count in number_dict
        :param total_num: int
        :param number_dict: dict
        :return: dict
        >>> num_dict = {'key1':0.1, 'key2':0.5}
        >>> VectorUtil.compute_idf_weight_dict(2, num_dict)
        {'key1': 1.0033021088637848, 'key2': 0.6931471805599453}
        """
        if number_dict is None:
            return {}
        if total_num is None:
            total_num = 0

        result = {}
        for k, v in number_dict.items():
            count = 0.0 if v is None else float(v)
            result[k] = float(np.log((total_num + 1.0) / (count + 1.0)))
        return result

class Words2Numbers:
    """
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    """

    def __init__(self):
        """
        Initialize the word lists and dictionaries required for conversion
        """
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            if word:
                self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    def _normalize_tokens(self, textnum):
        textnum = textnum.lower().strip().replace("-", " ")
        if not textnum:
            return []
        return textnum.split()

    def _to_cardinal_word(self, word):
        if word in self.numwords:
            return word
        if word in self.ordinal_words:
            value = self.ordinal_words[word]
            return self.units[value] if 0 <= value < len(self.units) else None
        for ending, replacement in self.ordinal_endings:
            if word.endswith(ending):
                candidate = word[:-len(ending)] + replacement
                if candidate in self.numwords:
                    return candidate
        return None

    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        if textnum is None:
            raise ValueError("Input cannot be None")
        if not isinstance(textnum, str):
            raise TypeError("Input must be a string")

        tokens = self._normalize_tokens(textnum)
        if not tokens:
            raise ValueError("Input cannot be empty")

        current = result = 0
        for raw_word in tokens:
            word = self._to_cardinal_word(raw_word)
            if word is None:
                raise ValueError(f"Illegal word: {raw_word}")

            scale, increment = self.numwords[word]
            current = current * scale + increment
            if scale > 100:
                result += current
                current = 0

        return str(result + current)

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        False
        """
        if textnum is None or not isinstance(textnum, str):
            return False

        # Match docstring example: hyphenated input should be invalid for this validator.
        if "-" in textnum:
            return False

        tokens = self._normalize_tokens(textnum)
        if not tokens:
            return False

        for raw_word in tokens:
            if self._to_cardinal_word(raw_word) is None:
                return False
        return True
